/**
 * Two ways we talk to PayPal:
 *
 * 1. The official PayPal Server SDK (`@paypal/paypal-server-sdk`, generated by
 *    APIMatic). Used for everything it covers: vault, orders, authorize,
 *    capture, void, refunds, tracking and transaction search.
 * 2. A tiny `rest()` helper with `fetch` for the few endpoints the SDK does not
 *    cover (webhook signature verification, setup-token approval links).
 *
 * Analogy: the SDK is a phrasebook written by PayPal; `rest()` is us speaking
 * directly for the few sentences the phrasebook is missing.
 */
import axios from "axios";
import { Client, Environment, LogLevel } from "@paypal/paypal-server-sdk";
import { env, paypalApiBase } from "../env";

const SANDBOX = "https://api-m.sandbox.paypal.com";
const LIVE = "https://api-m.paypal.com";

let sdk: Client | undefined;

/**
 * The SDK always talks to PayPal's real servers. For local development and
 * tests we can point it at our fake PayPal (PAYPAL_API_BASE) by swapping the
 * host inside its HTTP adapter. In production this rewrite is never used.
 */
function rewriteAdapter(target: string) {
  const http = axios.getAdapter("http");
  return (config: Parameters<typeof http>[0]) => {
    if (config.url) config.url = config.url.replace(SANDBOX, target).replace(LIVE, target);
    return http(config);
  };
}

export function getPayPal(): Client {
  if (!sdk) {
    const e = env();
    const overrideBase = e.PAYPAL_API_BASE;
    sdk = new Client({
      clientCredentialsAuthCredentials: {
        oAuthClientId: e.PAYPAL_CLIENT_ID || "fake-client",
        oAuthClientSecret: e.PAYPAL_CLIENT_SECRET || "fake-secret",
      },
      environment: e.PAYPAL_ENV === "live" ? Environment.Production : Environment.Sandbox,
      timeout: 20_000,
      logging: { logLevel: LogLevel.Error, logRequest: { logBody: false }, logResponse: { logBody: false } },
      ...(overrideBase ? { unstable_httpClientOptions: { adapter: rewriteAdapter(overrideBase) } } : {}),
    });
  }
  return sdk;
}

/** Tests call this after changing env vars. */
export function resetPayPal() {
  sdk = undefined;
  token = undefined;
}

// ─── fetch helper with a cached access token ──────────────────────────────

let token: { value: string; expiresAt: number } | undefined;

export async function accessToken(): Promise<string> {
  if (token && token.expiresAt > Date.now() + 60_000) return token.value;
  const e = env();
  const basic = Buffer.from(`${e.PAYPAL_CLIENT_ID || "fake-client"}:${e.PAYPAL_CLIENT_SECRET || "fake-secret"}`).toString("base64");
  const res = await fetch(`${paypalApiBase()}/v1/oauth2/token`, {
    method: "POST",
    headers: { Authorization: `Basic ${basic}`, "Content-Type": "application/x-www-form-urlencoded" },
    body: "grant_type=client_credentials",
  });
  if (!res.ok) throw new PayPalError(`PayPal login failed (${res.status})`, res.status, await res.text());
  const body = (await res.json()) as { access_token: string; expires_in: number };
  token = { value: body.access_token, expiresAt: Date.now() + body.expires_in * 1000 };
  return token.value;
}

export class PayPalError extends Error {
  constructor(
    message: string,
    public status: number,
    public details?: unknown,
  ) {
    super(message);
    this.name = "PayPalError";
  }
}

export async function rest<T>(
  method: "GET" | "POST" | "PATCH" | "DELETE",
  path: string,
  body?: unknown,
  headers: Record<string, string> = {},
): Promise<T> {
  const res = await fetch(`${paypalApiBase()}${path}`, {
    method,
    headers: {
      Authorization: `Bearer ${await accessToken()}`,
      "Content-Type": "application/json",
      ...headers,
    },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  const data = text ? JSON.parse(text) : undefined;
  if (!res.ok) throw new PayPalError(`PayPal ${method} ${path} failed (${res.status})`, res.status, data);
  return data as T;
}
